var w = 640, h = 200;
var svg = d3.select(this).append('svg').attr('viewBox', `0 0 ${w} ${h}`);
var nodes = [
  { id: 'User', x: 120, y: 100 },
  { id: 'Post', x: 460, y: 100 }
];
// Edge between the two entities.
svg.append('line').attr('class','edge')
  .attr('x1', nodes[0].x + 60).attr('y1', nodes[0].y)
  .attr('x2', nodes[1].x - 60).attr('y2', nodes[1].y);
// "one" / "many" crow's-foot-ish labels.
svg.append('text').attr('class','label').attr('x', nodes[0].x + 70).attr('y', nodes[0].y - 8).text('1');
svg.append('text').attr('class','label').attr('x', nodes[1].x - 80).attr('y', nodes[1].y - 8).text('*');
// Entity boxes.
var g = svg.selectAll('g.entity').data(nodes).enter().append('g')
  .attr('transform', d => `translate(${d.x - 60},${d.y - 30})`);
g.append('rect').attr('width', 120).attr('height', 60).attr('rx', 6)
  .attr('fill', '#eff6ff').attr('stroke', 'var(--accent)');
g.append('text').attr('class','label').attr('x', 60).attr('y', 35).attr('text-anchor','middle').text(d => d.id);

var steps = ['request', 'router', 'controller', 'service', 'database', 'response'];
var w = 640, h = 140;
var svg = d3.select(this).append('svg').attr('viewBox', `0 0 ${w} ${h}`);
var state = { i: 0 };
var x = d3.scalePoint().domain(steps).range([40, w - 40]);
// Base line.
svg.append('line').attr('class','edge').attr('x1', 40).attr('x2', w - 40).attr('y1', 50).attr('y2', 50);
// Step nodes.
var node = svg.selectAll('circle').data(steps).enter().append('circle')
  .attr('cx', d => x(d)).attr('cy', 50).attr('r', 10).attr('class','node');
svg.selectAll('text.label').data(steps).enter().append('text').attr('class','label')
  .attr('x', d => x(d)).attr('y', 80).attr('text-anchor','middle').text(d => d);
// Highlight the active step.
var marker = svg.append('circle').attr('cx', x(steps[0])).attr('cy', 50).attr('r', 16)
  .attr('fill','none').attr('stroke','var(--accent)').attr('stroke-width', 3);
// Controls.
var btns = d3.select(this).append('div').style('text-align','center').style('margin-top','0.5rem');
function render() { marker.attr('cx', x(steps[state.i])); }
btns.append('button').text('← prev').on('click', () => { state.i = Math.max(0, state.i - 1); render(); });
btns.append('span').text(' ');
btns.append('button').text('next →').on('click', () => { state.i = Math.min(steps.length - 1, state.i + 1); render(); });
render();

var data = [
  { name: '/list',   ms: 12 },
  { name: '/search', ms: 48 },
  { name: '/export', ms: 190 },
  { name: '/login',  ms: 35 }
];
var w = 560, h = 220, m = { top: 20, right: 20, bottom: 40, left: 50 };
var iw = w - m.left - m.right, ih = h - m.top - m.bottom;
var svg = d3.select(this).append('svg').attr('viewBox', `0 0 ${w} ${h}`)
  .append('g').attr('transform', `translate(${m.left},${m.top})`);
var x = d3.scaleBand().domain(data.map(d => d.name)).range([0, iw]).padding(0.2);
var y = d3.scaleLinear().domain([0, d3.max(data, d => d.ms)]).range([ih, 0]);
svg.append('g').attr('class','axis').attr('transform', `translate(0,${ih})`).call(d3.axisBottom(x));
svg.append('g').attr('class','axis').call(d3.axisLeft(y).ticks(4));
svg.selectAll('rect.bar').data(data).enter().append('rect').attr('class','node')
  .attr('x', d => x(d.name)).attr('y', d => y(d.ms))
  .attr('width', x.bandwidth()).attr('height', d => ih - y(d.ms));

