var nodes = [
  { id: 'A', x: 80,  y: 60, fails: false },
  { id: 'B', x: 240, y: 60, fails: false },
  { id: 'C', x: 400, y: 60, fails: true }  // C times out when B is down
];
var w = 480, h = 140;
var svg = d3.select(this).append('svg').attr('viewBox', `0 0 ${w} ${h}`);
// Edges A->B, B->C
[[0,1],[1,2]].forEach(function(pair){
  svg.append('line').attr('class','edge')
    .attr('x1', nodes[pair[0]].x).attr('y1', nodes[pair[0]].y)
    .attr('x2', nodes[pair[1]].x).attr('y2', nodes[pair[1]].y);
});
var g = svg.selectAll('g.node').data(nodes).enter().append('g')
  .style('cursor','pointer')
  .on('click', function(event, d){
    nodes.forEach(function(n){ n.selected = (n === d); });
    g.select('circle').attr('class', function(n){ return n.selected ? 'node-fail' : 'node'; });
  });
g.append('circle').attr('class','node').attr('cx', function(d){ return d.x; }).attr('cy', function(d){ return d.y; }).attr('r', 22);
g.append('text').attr('class','label').attr('x', function(d){ return d.x; }).attr('y', function(d){ return d.y + 5; }).attr('text-anchor','middle').text(function(d){ return d.id; });

